module alu (
	input [31:0] a,
	input [31:0] b,
	input [5:0] aluc,
	output [31:0] r,
	output zero,
	output carry,
	output negative,
	output overflow,
	output flag
);
	// TODO: Please add your logic design here

	reg [32:0] res;
	wire [31:0] signed_a;
	wire [31:0] signed_b;

	assign signed_a = $signed(a);
	assign signed_b = $signed(b);
	assign r = res[31:0];
	assign zero = (res[31:0] == 0);
	assign negative = res[31];
	assign flag = (aluc == 6'b101010 || aluc == 6'b101011) ? ((aluc == 6'b101010) ? ($signed(signed_a) < $signed(signed_b)) : (a < b)) : 1'b0;
	assign carry = (aluc == 6'b100000 || aluc == 6'b100001 || aluc == 6'b100010 || aluc == 6'b100011) ? res[32] : 1'b0;
	assign overflow = (aluc == 6'b100000 || aluc == 6'b100010) ? (((~signed_a[31] & ~signed_b[31] & res[31]) | (signed_a[31] & signed_b[31] & ~res[31])) ? 1 : 0) : 1'b0;
	always @ (*) begin
		case (aluc)
			6'b100000: res = $signed(signed_a + signed_b);
			6'b100001: res = $unsigned(a + b);
			6'b100010: res = $signed(signed_a - signed_b);
			6'b100011: res = $unsigned(a - b);
			6'b100100: res = a & b;
			6'b100101: res = a | b;
			6'b100110: res = a ^ b;
			6'b100111: res = ~(a | b);
			6'b101010: res = (($signed(signed_a) < $signed(signed_b))) ? 1 : 0;
			6'b101011: res = (a < b) ? 1 : 0;
			6'b000000: res = b << a[4:0];
			6'b000010: res = b >> a[4:0];
			6'b000011: res = signed_b >>> a[4:0];
			6'b000100: res = b << a[4:0];
			6'b000110: res = b >> a[4:0];
			6'b000111: res = signed_b >>> a[4:0];
			6'b001111: res = {a[15:0], 16'h0};
			default: res = 32'hzzzzzzzz;
		endcase
	end
endmodule
